--
-- Name: intake_state tenant_access; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY tenant_access ON public.intake_state USING ((version_id IN ( SELECT v.version_id
   FROM (((public.versions v
     JOIN public.scenarios s ON ((s.scenario_id = v.scenario_id)))
