     JOIN public.users u ON ((u.tenant_id = p.tenant_id)))
  WHERE (u.user_id = auth.uid())))) WITH CHECK ((version_id IN ( SELECT v.version_id
   FROM (((public.versions v
     JOIN public.scenarios s ON ((s.scenario_id = v.scenario_id)))
     JOIN public.projects p ON ((p.project_id = s.project_id)))
     JOIN public.users u ON ((u.tenant_id = p.tenant_id)))
  WHERE (u.user_id = auth.uid()))));


